window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-40a733b28f3bc5a9"]={"versions": [{"id": "FIG-40a733b28f3bc5a9", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-basiertes Prozessdiagramm) im Kontext des AUTOSAR-Entwicklungsprozesses für die Definition von Speichermapping-Adressierungsmodi (<code>MemMapAddressingModeSet</code>). Es beschreibt die Rollenbeteiligung und die Artefakterzeugung bei der Festlegung von Adressierungsmodi für Basissoftware-Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Module Developer</code> (Kardinalität <code>1</code>)</li>\n<li><code>Software Component Developer</code> (Kardinalität <code>0..1</code>)</li>\n<li><strong>Aktivität</strong>:</li>\n<li><code>Define Memory Addressing Modes</code> (Aktivitätsform)</li>\n<li><strong>Artefakt</strong>:</li>\n<li><code>BSW Module Description</code> (Dokumentensymbol, unten rechts beschriftet mit <code>BSW Module...</code>)</li>\n<li><strong>Beziehungen & Stereotypen</strong>:</li>\n<li><code>«performs»</code>: Gerichtet von <code>Basic Software Module Developer</code> auf die Aktivität (Kardinalität <code>1</code>).</li>\n<li><code>«performs»</code>: Gerichtet von <code>Software Component Developer</code> auf die Aktivität (Kardinalität <code>0..1</code>).</li>\n<li><code>«output»</code>: Gerichtet von <code>Define Memory Addressing Modes</code> auf das Artefakt mit der Rollenbezeichnung <code>+MemMapAddressingModeSet</code> und der Multiplizität <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define Memory Addressing Modes</code> wird obligatorisch durch genau einen <code>Basic Software Module Developer</code> ausgeführt, optional unterstützt durch bis zu einen <code>Software Component Developer</code> (<code>0..1</code>). Das Ergebnis der Ausführung ist die Erzeugung oder Aktualisierung von mindestens einem <code>MemMapAddressingModeSet</code> (<code>1..*</code>), das als <code>«output»</code> in die Beschreibungsdaten des BSW-Moduls einfließt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Festlegung der Adressierungsmodi ist eine zwingende Aufgabe des BSW-Entwicklers, während der SWC-Entwickler nur bedarfsweise beigezogen wird (z. B. zur Harmonisierung applikationsspezifischer Adressierungsanforderungen). Die Aktivität muss zwingend mindestens ein konsistentes <code>MemMapAddressingModeSet</code> (<code>1..*</code>) für die BSW-Modulbeschreibung bereitstellen, um eine korrekte Zuordnung im Memory Mapping sicherzustellen.</p>"}, {"id": "FIG-aad41ca6771e2e22", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-basiertes Prozessdiagramm) im Kontext des AUTOSAR-Entwicklungsprozesses für die Definition von Speichermapping-Adressierungsmodi (<code>MemMapAddressingModeSet</code>). Es beschreibt die Rollenbeteiligung und die Artefakterzeugung bei der Festlegung von Adressierungsmodi für Basissoftware-Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Module Developer</code> (Kardinalität <code>1</code>)</li>\n<li><code>Software Component Developer</code> (Kardinalität <code>0..1</code>)</li>\n<li><strong>Aktivität</strong>:</li>\n<li><code>Define Memory Addressing Modes</code> (Aktivitätsform)</li>\n<li><strong>Artefakt</strong>:</li>\n<li><code>BSW Module Description</code> (Dokumentensymbol, unten rechts beschriftet mit <code>BSW Module...</code>)</li>\n<li><strong>Beziehungen & Stereotypen</strong>:</li>\n<li><code>«performs»</code>: Gerichtet von <code>Basic Software Module Developer</code> auf die Aktivität (Kardinalität <code>1</code>).</li>\n<li><code>«performs»</code>: Gerichtet von <code>Software Component Developer</code> auf die Aktivität (Kardinalität <code>0..1</code>).</li>\n<li><code>«output»</code>: Gerichtet von <code>Define Memory Addressing Modes</code> auf das Artefakt mit der Rollenbezeichnung <code>+MemMapAddressingModeSet</code> und der Multiplizität <code>1..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define Memory Addressing Modes</code> wird obligatorisch durch genau einen <code>Basic Software Module Developer</code> ausgeführt, optional unterstützt durch bis zu einen <code>Software Component Developer</code> (<code>0..1</code>). Das Ergebnis der Ausführung ist die Erzeugung oder Aktualisierung von mindestens einem <code>MemMapAddressingModeSet</code> (<code>1..*</code>), das als <code>«output»</code> in die Beschreibungsdaten des BSW-Moduls einfließt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Festlegung der Adressierungsmodi ist eine zwingende Aufgabe des BSW-Entwicklers, während der SWC-Entwickler nur bedarfsweise beigezogen wird (z. B. zur Harmonisierung applikationsspezifischer Adressierungsanforderungen). Die Aktivität muss zwingend mindestens ein konsistentes <code>MemMapAddressingModeSet</code> (<code>1..*</code>) für die BSW-Modulbeschreibung bereitstellen, um eine korrekte Zuordnung im Memory Mapping sicherzustellen.</p>"}], "trans": [{"from": "FIG-40a733b28f3bc5a9", "to": "FIG-aad41ca6771e2e22", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
